        # This is too big for a simple backtrack.
        # Let's use a different approach: BFS or recursion with memoization.

        memo = {}
        def backtrack(grid_tuple):
            if all(grid_tuple):
                return 0

            # Find first empty cell
            x, y = -1, -1
            for i in range(w):
                for j in range(h):
                    if not grid_tuple[i*h + j]:
