def solve():
    # S-tetraminoes
    base_s = {(0,1), (0,2), (1,0), (1,1)}
    shapes = []
    def rotate(shape):
        return {(-y, x) for x, y in shape}
    def reflect(shape):
        return {(x, -y) for x, y in shape}
    current = base_s
    for _ in range(4):
        current = rotate(current)
        shapes.append(current)
        shapes.append(reflect(current))
    normalized_shapes = []
    for s in shapes:
        min_x = min(x for x, y in s)
        min_y = min(y for x, y in s)
        normalized = frozenset((x - min_x, y - min_y) for x, y in s)
        if normalized not in normalized_shapes:
            normalized_shapes.append(normalized)

    memo = {}
    def get_min_dominoes(grid):
        if grid in memo:
            return memo[grid]
        first_empty = None
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] == 0:
                    first_empty = (r, c)
                    break
            if first_empty:
                break
        if not first_empty:
            return 0
        r, c = first_empty
        res = float('inf')
        # Horizontal domino
        if c + 1 < len(grid[0]) and grid[r][c+1] == 0:
            new_grid = [list(row) for row in grid]
            new_grid[r][c] = 1
            new_grid[r][c+1] = 1
            res = min(res, 1 + get_min_dominoes(tuple(tuple(row) for row in new_grid)))
        # Vertical domino
        if r + 1 < len(grid) and grid[r+1][c] == 0:
            new_grid = [list(row) for row in grid]
            new_grid[r][c] = 1
            new_grid[r+1][c] = 1
            res = min(res, 1 + get_min_dominoes(tuple(tuple(row) for row in new_grid)))
        # S-tetraminoes
        for shape in normalized_shapes:
            for dr, dc in shape:
                offset_r = r - dr
                offset_c = c - dc
                possible = True
                cells_to_fill = []
                for sx, sy in shape:
                    nr, nc = offset_r + sx, offset_c + sy
                    if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == 0:
                        cells_to_fill.append((nr, nc))
                    else:
                        possible = False
                        break
                if possible:
                    new_grid = [list(row) for row in grid]
                    for nr, nc in cells_to_fill:
                        new_grid[nr][nc] = 1
                    res = min(res, get_min_dominoes(tuple(tuple(row) for row in new_grid)))
        memo[grid] = res
        return res

    results = {}
    for W in range(1, 11):
        initial_grid = tuple(tuple(0 for _ in range(W)) for _ in range(22))
        results[W] = get_min_dominoes(initial_grid)
    return results

