def solve_small(H, W):
    # S-tetraminoes orientations
    s_tetraminoes = [
        {(0, 1), (0, 2), (1, 0), (1, 1)}, # 2x3
        {(0, 1), (1, 0), (1, 1), (2, 0)}, # 3x2
        {(0, 0), (0, 1), (1, 1), (1, 2)}, # 2x3
        {(0, 0), (1, 0), (1, 1), (2, 1)}  # 3x2
    ]
    dominoes = [
        {(0, 0), (0, 1)}, # 1x2
        {(0, 0), (1, 0)}  # 2x1
    ]

    memo = {}

    def backtrack(grid):
        state = tuple(tuple(row) for row in grid)
        if state in memo:
            return memo[state]

        r, c = -1, -1
        for i in range(H):
            for j in range(W):
                if grid[i][j] == 0:
                    r, c = i, j
                    break
            if r != -1: break

        if r == -1:
            return 0

        res = float('inf')

        # Try S-tetraminoes
        for shape in s_tetraminoes:
            for sr, sc in shape:
                offset_r = r - sr
                offset_c = c - sc

                possible = True
                new_coords = []
                for r_i, c_i in shape:
                    nr, nc = r_i + offset_r, c_i + offset_c
                    if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == 0:
                        new_coords.append((nr, nc))
                    else:
                        possible = False
                        break

                if possible:
                    for nr, nc in new_coords:
                        grid[nr][nc] = 1
                    res = min(res, backtrack(grid))
                    for nr, nc in new_coords:
                        grid[nr][nc] = 0

        # Try dominoes
        for shape in dominoes:
            for sr, sc in shape:
                offset_r = r - sr
                offset_c = c - sc

                possible = True
                new_coords = []
                for r_i, c_i in shape:
                    nr, nc = r_i + offset_r, c_i + offset_c
                    if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == 0:
                        new_coords.append((nr, nc))
                    else:
                        possible = False
                        break

                if possible:
                    for nr, nc in new_coords:
                        grid[nr][nc] = 1
                    res = min(res, 1 + backtrack(grid))
                    for nr, nc in new_coords:
                        grid[nr][nc] = 0

        memo[state] = res
        return res

    initial_grid = [[0 for _ in range(W)] for _ in range(H)]
    return backtrack(initial_grid)

